   <main class="quiz-card">
     <h1>Computer Languages Quiz</h1>
     <p class="intro">Choose all answers that apply for each question, then submit to review what you picked.</p>

     <form id="quiz-form">
       <div class="form-field">
         <span class="question-title">1. Which of these are commonly used for web development?</span>
         <p class="help-text">Select every language that is widely used to build websites or web applications.</p>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q1" value="JavaScript">JavaScript</label>
           <label class="choice"><input type="checkbox" name="q1" value="Python">Python</label>
           <label class="choice"><input type="checkbox" name="q1" value="HTML">HTML</label>
           <label class="choice"><input type="checkbox" name="q1" value="SQL">SQL</label>
         </div>
       </div>

       <div class="form-field">
         <span class="question-title">2. Which of these are compiled programming languages?</span>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q2" value="C++">C++</label>
           <label class="choice"><input type="checkbox" name="q2" value="Go">Go</label>
           <label class="choice"><input type="checkbox" name="q2" value="Ruby">Ruby</label>
           <label class="choice"><input type="checkbox" name="q2" value="Java">Java</label>
         </div>
       </div>

       <div class="form-field">
         <span class="question-title">3. Which of these are used for querying or managing data?</span>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q3" value="SQL">SQL</label>
           <label class="choice"><input type="checkbox" name="q3" value="GraphQL">GraphQL</label>
           <label class="choice"><input type="checkbox" name="q3" value="Kotlin">Kotlin</label>
           <label class="choice"><input type="checkbox" name="q3" value="R">R</label>
         </div>
       </div>

       <div class="actions">
         <button type="submit">Submit Quiz</button>
         <div id="result" class="result" aria-live="polite"></div>
       </div>
     </form>
   </main>

   <script>
     const form = document.getElementById('quiz-form');
     const result = document.getElementById('result');

